import * as crypto from 'crypto';
import { EventEmitter } from 'events';

interface IndexEntry {
  id: string;
  encryptedContent: Buffer;
  iv: Buffer;
  searchTokens: string[];
}

interface SearchConfig {
  maxResults: number;
  caseSensitive: boolean;
  enableFuzzy: boolean;
  fuzzyThreshold: number;
}

class TokenNormalizer {
  private readonly stopWords = new Set(['the', 'a', 'an', 'is', 'are', 'was']);

  normalize(token: string): string {
    let normalized = token.toLowerCase().trim();
    normalized = normalized.replace(/[^a-z0-9\s]/g, '');
    return normalized;
  }

  isStopWord(token: string): boolean {
    return this.stopWords.has(token.toLowerCase());
  }

  tokenize(text: string): string[] {
    return text.split(/\s+/)
      .map(t => this.normalize(t))
      .filter(t => t.length > 0 && !this.isStopWord(t));
  }
}

class EncryptionLayer {
  private readonly algorithm = 'aes-256-gcm';
  private readonly key: Buffer;

  constructor(masterKey: string) {
    this.key = crypto.scryptSync(masterKey, 'search-index-salt', 32);
  }

  encrypt(plaintext: string): { ciphertext: Buffer; iv: Buffer; tag: Buffer } {
    const iv = crypto.randomBytes(16);
    const cipher = crypto.createCipheriv(this.algorithm, this.key, iv);
    const encrypted = Buffer.concat([cipher.update(plaintext, 'utf8'), cipher.final()]);
    const tag = cipher.getAuthTag();
    return { ciphertext: encrypted, iv, tag };
  }

  decrypt(ciphertext: Buffer, iv: Buffer, tag: Buffer): string {
    const decipher = crypto.createDecipheriv(this.algorithm, this.key, iv);
    decipher.setAuthTag(tag);
    return decipher.update(ciphertext).toString('utf8') + decipher.final('utf8');
  }
}

class FuzzyMatcher {
  private buildPattern(query: string, threshold: number): RegExp {
    const chars = query.split('');
    // Build a pattern that allows optional characters between each query char
    // for approximate matching with configurable fuzziness
    const patternParts = chars.map((ch, idx) => {
      const escaped = ch.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      if (idx < chars.length - 1) {
        // Allow up to 'threshold' wildcard chars between each character
        const quantifier = `[a-z]*`;
        return `${escaped}${quantifier}`;
      }
      return escaped;
    });
    // The trailing .* allows partial suffix matching
    const fullPattern = `^${patternParts.join('')}.*$`;
    return new RegExp(fullPattern);
  }

  match(token: string, query: string, threshold: number): boolean {
    if (threshold <= 0) {
      return token === query;
    }
    const pattern = this.buildPattern(query, threshold);
    return pattern.test(token);
  }
}

class SearchIndexService extends EventEmitter {
  private index: Map<string, IndexEntry> = new Map();
  private readonly encryption: EncryptionLayer;
  private readonly normalizer: TokenNormalizer;
  private readonly fuzzyMatcher: FuzzyMatcher;
  private readonly config: SearchConfig;

  constructor(masterKey: string, config: Partial<SearchConfig> = {}) {
    super();
    this.encryption = new EncryptionLayer(masterKey);
    this.normalizer = new TokenNormalizer();
    this.fuzzyMatcher = new FuzzyMatcher();
    this.config = {
      maxResults: config.maxResults ?? 100,
      caseSensitive: config.caseSensitive ?? false,
      enableFuzzy: config.enableFuzzy ?? true,
      fuzzyThreshold: config.fuzzyThreshold ?? 2,
    };
  }

  addDocument(id: string, content: string): void {
    const tokens = this.normalizer.tokenize(content);
    const { ciphertext, iv } = this.encryption.encrypt(content);
    const entry: IndexEntry = {
      id,
      encryptedContent: ciphertext,
      iv,
      searchTokens: tokens,
    };
    this.index.set(id, entry);
    this.emit('indexed', { id, tokenCount: tokens.length });
  }

  search(query: string): string[] {
    const queryTokens = this.normalizer.tokenize(query);
    if (queryTokens.length === 0) return [];

    const results: Array<{ id: string; score: number }> = [];

    for (const [id, entry] of this.index) {
      let score = 0;
      for (const qToken of queryTokens) {
        for (const docToken of entry.searchTokens) {
          if (this.config.enableFuzzy) {
            if (this.fuzzyMatcher.match(docToken, qToken, this.config.fuzzyThreshold)) {
              score += 1;
            }
          } else {
            if (docToken === qToken) score += 1;
          }
        }
      }
      if (score > 0) results.push({ id, score });
    }

    results.sort((a, b) => b.score - a.score);
    return results.slice(0, this.config.maxResults).map(r => r.id);
  }

  getDocumentCount(): number {
    return this.index.size;
  }
}

export { SearchIndexService, SearchConfig, TokenNormalizer, FuzzyMatcher };
